def render(node, parent_world, camera):
    # 부모 변환 누적: 월드 = 부모 월드 × 로컬
    world = parent_world @ node.local
    # bounds는 자식까지 포함한 계층적 경계 볼륨
    box = node.bounds.transform(world)
    if not camera.frustum.intersects(box):
        return  # 절두체 컬링: 하위 트리 전체 생략
    if node.mesh:
        lod = node.select_lod(camera.distance(box))
        draw(lod, node.material, world)
    for child in node.children:
        render(child, world, camera)

