def response_time(tasks, i, b=0):
    # tasks: 우선순위 내림차순 [(C, T)], 마감 = 주기
    c, t = tasks[i]
    r = c + b  # b: 블로킹 시간
    while True:
        # 상위 태스크 간섭: ceil(r/Tj) × Cj
        interf = sum(-(-r // tj) * cj
                     for cj, tj in tasks[:i])
        r_new = c + b + interf
        if r_new > t:
            return None  # 마감 초과
        if r_new == r:
            return r  # 수렴: 최악 응답시간
        r = r_new

def schedulable(tasks):
    return all(response_time(tasks, i) is not None
               for i in range(len(tasks)))
